/* This file is generated by scripts/tea-reference-markdown/build-pages.mjs from
 * data/tea-reference/entries/: approved composed entries only, keyed by product id. */
import type { ComposedEntry } from './composedEntry';

export const GENERATED_ENTRIES: Readonly<Record<string, ComposedEntry>> = {
  "00b13369-8aa6-40e9-9d9a-0f26a28bc7ff": {"productId":"00b13369-8aa6-40e9-9d9a-0f26a28bc7ff","paragraphs":[{"layer":"grade","text":"Gongjian, the [tribute tip](anhua-dark:family), is one of the three loose tips of Anhua tea, lightly pressed into bamboo baskets rather than moulded into bricks or rolls. It sits in the middle of the three, between Tianjian above it and the coarser, stalkier Shengjian below, since the raw leaf is sorted into [numbered grades](anhua-dark:grades) and each tea is made from the grade that suits it. The loose tips grew out of the [Qing border trade](anhua-dark:history) to the north-west."},{"layer":"place","text":"The leaf comes from Anhua County, a mountain county on the Zi river in Hunan and a protected origin for [Anhua dark tea](anhua-dark:definition). Like every Anhua tea it began as one raw tea, [heimaocha](anhua-dark:making): fixed, rolled, piled, rolled again and dried, then steamed soft and pressed lightly, as the loose tips are."},{"layer":"age","text":"This is a 2024 tea, two years old. Anhua tea is [kept for years](anhua-dark:ageing) and said to improve as it rests, though no agreed count of years marks it as aged. Kept clean, dry and aired, away from other smells, it can be left to change over the years ahead."}],"brewing":{"layer":"brewing","text":"In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"Anhua dark tea","text":"Pine smoke or pine resin above all, a sweet taste and aftertaste, and a mellow, thick, smooth cup; a liquor from yellow and orange to orange-red. Young tea is often smokier in the first infusions and a little bitter, sweetening as the infusions go on."},"missing":[]},
  "04729b3d-cf32-4bf8-b9a1-8695e247e403": {"productId":"04729b3d-cf32-4bf8-b9a1-8695e247e403","paragraphs":[{"layer":"type","text":"[Meizhan](yancha:meizhan) is a Fujian cultivar that came from Anxi and is also made as [Wuyi rock tea](yancha:definition). It is less known than Rougui and Shui Xian and sits outside the four famous bushes of Wuyi. This leaf, from 1990, grew in the Wuyi Mountains, the only area whose tea may carry the rock tea name, where the bushes root among crevices, ledges and terraces in cliff country. It was twisted into long thin strips and finished over charcoal in several rounds, a [roast](yancha:making) that dries the leaf so it keeps."},{"layer":"age","text":"Rock tea meant for [keeping](yancha:ageing) is the medium to full roast kind, since the heavier the roast, the longer it is said to stay good. Over thirty-six years, damp is the main risk. Tea that takes on moisture can go green again, fǎn qīng, the main fault of stored rock tea, so a tea kept this long has to stay sealed, dry and cool, and be checked now and then."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"aged Wuyi rock tea","text":"A smoother, thicker liquor with less sharpness, the roast softened and the high aroma faded."},"missing":[]},
  "186380ba-6839-448f-baaf-2b84ef7e5556": {"productId":"186380ba-6839-448f-baaf-2b84ef7e5556","paragraphs":[{"layer":"named","text":"The name reads as a place, a description and a style. [Mahei](mahei-gushu-red:tea-name) is the village in Yiwu, gushu means old tree, as the label describes it, and hong cha means red tea. A section of the old [Tea Horse Road](mahei:village-road-and-harvest) passes through the village, and in April 2024 the farmer Ding Wanchun told local reporters his family needed more than twenty pickers a day for the spring harvest."},{"layer":"type","text":"The leaf was made into [red tea](red:definition), the fully oxidised tea English calls black. It was [withered, then rolled](dian-hong:making) to break its cells so oxidation could begin, left until it turned from green to reddish brown, and then dried. It belongs to the newer branch sold as [old-tree red](dian-hong:old-tree-and-sun-dried), which has no agreed definition or standard."},{"layer":"age","text":"This is a 2025 tea, one year old. Yunnan red tea is [kept for freshness](dian-hong:ageing) rather than for age, and the trade drinks it within its first one to three years."}],"brewing":{"layer":"brewing","text":"Dian Hong takes hot water, roughly 90 to 100°C. A common start is about 5 grams to 100 ml, with short steeps that lengthen slowly as the leaf opens."},"notice":{"layer":"notice","styleName":"Dian Hong","text":"A full, sweet cup, often described as malty, with chocolate or cocoa and honey notes and sometimes something floral. The liquor runs golden to bright red, and a good grade has little bitterness."},"missing":[]},
  "2205c8f5-bcc9-4ec2-823b-fecf68db56fb": {"productId":"2205c8f5-bcc9-4ec2-823b-fecf68db56fb","paragraphs":[{"layer":"age","text":"This ripe pu’er cake dates to 2015 and is listed as Pasha, Menghai. As ripe pu’er rests, the [air and moisture](shou:age-aged) around the leaves shape how its aroma develops."}],"missing":[]},
  "28436463-2272-4f68-83e1-b6d86f798be2": {"productId":"28436463-2272-4f68-83e1-b6d86f798be2","paragraphs":[{"layer":"lot","text":"This ripe pu’er brick is from Yunnan and dates to 1990. Ripe pu’er gets its character from [wet piling](shou:wet-piling), a process in which damp tea leaves ferment before the tea is dried."}],"missing":[]},
  "2c43aa09-e47e-4f14-8f0c-f6ef8f871683": {"productId":"2c43aa09-e47e-4f14-8f0c-f6ef8f871683","paragraphs":[{"layer":"place","text":"This is [Wuyi rock tea](yancha:definition), the [oolong](oolong:definition) of the Wuyi Mountains in northern Fujian. Only leaf from that area may be sold under the name. The bushes grow among rock, in crevices, on ledges and on cliff terraces. They root in soil weathered from the stone, in country with much fog and rain."},{"layer":"type","text":"The leaf is twisted into long, narrow strips rather than rolled into balls. It is then finished with a [charcoal roast](yancha:making) given in several rounds, with rests of weeks or months between them. The roast dries the tea so that it keeps, and its strength is matched to the leaf it is given."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Wuyi rock tea","text":"Roast and stone fruit, a mineral, rocky texture and a long, sweet, mouth-watering finish. Light roast is bright and floral, medium roast fruity and rounded, full roast charcoal, wood and roasted nuts. Da Hong Pao is often floral, Rougui spicy with cinnamon, young Shui Xian sweet and smooth, and old-bush Shui Xian woody and mossy."},"missing":[]},
  "2d489d83-99ce-4a0d-ad45-ddb4bf0430e5": {"productId":"2d489d83-99ce-4a0d-ad45-ddb4bf0430e5","paragraphs":[{"layer":"type","text":"[Meizhan](yancha:meizhan) is a Fujian cultivar that came from Anxi, and here it is made as [Wuyi rock tea](yancha:definition), the oolong of the Wuyi mountains in northern Fujian. It is not one of the four famous bushes of Wuyi, and it is less famous than Rougui or Shui Xian. The bushes of this area grow among rock, on ledges and terraces in cliff country. The leaf is finished over charcoal in several rounds, with rests between them, and that [charcoal roast](yancha:making) dries the tea so it keeps."},{"layer":"age","text":"This leaf was made in 2004, so it has had twenty-two years. The rock tea that gets kept this long is the medium to full roast kind, and the heavier the roast, the longer it is said to hold. Damp is the real danger in storage. Tea that takes it on [goes green again](yancha:ageing), and a careful low roast can drive the moisture back out."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"aged Wuyi rock tea","text":"A smoother, thicker liquor with less sharpness, the roast softened and the high aroma faded."},"missing":[]},
  "2ec4bcf5-1773-453c-b710-5b859203cb4e": {"productId":"2ec4bcf5-1773-453c-b710-5b859203cb4e","paragraphs":[{"layer":"age","text":"A [Liu Bao](liu-bao:definition) from Guangxi, made in 1990 and sold as loose leaf. At thirty-six years it sits far past the decade after which the trade counts this tea as [aged](liu-bao:age-aged), and how it was stored has shaped it as much as the years have."},{"layer":"type","text":"Liu Bao is the [dark tea](dark:definition) of Cangwu County, near Wuzhou, named for the town of Liubao where it began. As with every post-fermented tea, the leaf is piled after it is made, so warmth, moisture and microbes slowly turn it darker before it is packed and left to age. It was made for a market far from home: Chinese miners and labourers in the [tin mines of Malaya](liu-bao:nanyang-trade) drank it, and it travelled by boat down the river to Wuzhou, on to Guangzhou, and out by sea."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "30efe43d-7748-452c-9fb7-c04452a09cf3": {"productId":"30efe43d-7748-452c-9fb7-c04452a09cf3","paragraphs":[{"layer":"type","text":"A loose [Lapsang Souchong](lapsang:definition) from the Wuyi Mountains of Fujian, dated 1934. Lapsang Souchong is the Western name for Zhengshan Xiaozhong, the [red tea](red:definition) of Tongmu in the Wuyi mountains of northern Fujian. The style is called the [ancestor of red tea](lapsang:history), and it reached Europe through Dutch and then British trade."},{"layer":"age","text":"At ninety-two years this tea sits outside any known practice. Lapsang has [no recognised tradition of long ageing](lapsang:ageing), and no category of red tea kept for decades has been described. The change that is recorded for the style belongs to its first few years, in storage kept sealed, dry, cool and away from light."}],"brewing":{"layer":"brewing","text":"In a cup or pot, use about 3 grams for 240 ml, with water at 90 to 100°C, and steep about two to five minutes, usually around three. Gongfu style, use about 5 grams in a 100 to 110 ml gaiwan or pot, with short steeps that grow a little longer each round. Too hot or too long and the smoke turns harsh and bitter and covers the tea."},"notice":{"layer":"notice","styleName":"aged Lapsang Souchong","text":"The smoke softer and further back, with dried fruit coming forward."},"missing":[]},
  "35d3071e-570a-4a7c-a452-6b4568a62481": {"productId":"35d3071e-570a-4a7c-a452-6b4568a62481","paragraphs":[{"layer":"lot","text":"Huangye, 荒野, marks this as leaf picked from uncultivated tea plants growing wild in the mountains of [Anhua](anhua-dark:definition), a county on the Zi river in north-central Hunan whose dark tea is a protected origin product. The wild leaf was then made in the Anhua way, starting as [heimaocha](anhua-dark:making), the one raw tea behind every Anhua tea."},{"layer":"age","text":"Made in 2024, it is two years old. The slow change in warmth and moisture that makes [dark tea](dark:definition) what it is has only just begun in this leaf. Anhua tea is kept for years and said to improve, though no agreed count of years marks it as [aged](anhua-dark:ageing); kept clean, dry and aired, away from damp and other smells, it has a long way still to go."}],"brewing":{"layer":"brewing","text":"In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"Anhua dark tea","text":"Pine smoke or pine resin above all, a sweet taste and aftertaste, and a mellow, thick, smooth cup; a liquor from yellow and orange to orange-red. Young tea is often smokier in the first infusions and a little bitter, sweetening as the infusions go on."},"missing":[]},
  "3603a079-0aa8-4acd-958f-307322b037e5": {"productId":"3603a079-0aa8-4acd-958f-307322b037e5","paragraphs":[{"layer":"lot","text":"These are pieces of [ripe pu’er](shou:definition) cakes from the 1980s, made from Yunnan leaf and broken over the years, now sold loose. The cakes date from the style’s first two decades: Yunnan’s state factories only brought the [wet-pile method](shou:wet-piling) into production in 1973, heaping damp leaf so its own warmth could ferment it in weeks."},{"layer":"age","text":"At forty-one years the tea sits well within what the trade counts as [aged ripe pu’er](shou:age-aged). The leaf keeps changing slowly with the air and moisture around it, so storage has shaped these pieces as much as time has."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "3e29dc84-eb0d-4f18-bd71-702b18000b2a": {"productId":"3e29dc84-eb0d-4f18-bd71-702b18000b2a","paragraphs":[{"layer":"place","text":"This is [Rougui](yancha:rougui), a cultivar of the Wuyi mountains in northern Fujian that dates from the Qing dynasty and is now one of the most widely planted in the area. It is [Wuyi rock tea](yancha:definition), a name only leaf from these mountains may carry. The bushes grow among rock, on ledges and terraces in cliff country, rooted in soil weathered from the stone."},{"layer":"type","text":"The leaf is made the [oolong](oolong:definition) way: partly oxidised, then twisted into long strips rather than rolled into balls. The finish is a [charcoal roast](yancha:making), given in several rounds with weeks or months of rest between them. The roast dries the tea so that it keeps."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Wuyi rock tea","text":"Roast and stone fruit, a mineral, rocky texture and a long, sweet, mouth-watering finish. Light roast is bright and floral, medium roast fruity and rounded, full roast charcoal, wood and roasted nuts. Da Hong Pao is often floral, Rougui spicy with cinnamon, young Shui Xian sweet and smooth, and old-bush Shui Xian woody and mossy."},"missing":[]},
  "497f48ae-7ba0-4dc0-a051-36823ba40a9d": {"productId":"497f48ae-7ba0-4dc0-a051-36823ba40a9d","paragraphs":[{"layer":"lot","text":"A loose [Anhua dark tea](anhua-dark:definition) from 2022, made from wild-harvested leaf rather than garden-grown. Anhua is a mountain county on the Zi river in north-central Hunan, a protected place of origin and widely named the main home of dark tea in China."},{"layer":"type","text":"Like every tea from the county, it starts as [heimaocha](anhua-dark:making), the raw dark tea: large leaf fixed, rolled, piled, rolled again and dried. From there it keeps changing. Dark tea is [post-fermented](dark:definition): after the leaf is made, warmth, moisture, microbes and the leaf's own chemistry keep working on it."},{"layer":"age","text":"At four years, this one is early in that change. The trade keeps Anhua tea for years because it is said to improve, but no agreed count of years makes it [aged](anhua-dark:ageing)."}],"brewing":{"layer":"brewing","text":"In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"Anhua dark tea","text":"Pine smoke or pine resin above all, a sweet taste and aftertaste, and a mellow, thick, smooth cup; a liquor from yellow and orange to orange-red. Young tea is often smokier in the first infusions and a little bitter, sweetening as the infusions go on."},"missing":[]},
  "6876236c-bcc5-49d8-b918-5c5db02ca2a5": {"productId":"6876236c-bcc5-49d8-b918-5c5db02ca2a5","paragraphs":[{"layer":"lot","text":"Loose [ripe pu’er](shou:definition) from Yunnan, made in the 1990s and stored in Guangzhou. It was never pressed into a cake or brick, so air moves freely through the leaf and it ages along a more even path."},{"layer":"age","text":"The leaf was fermented in a covered [wet pile](shou:wet-piling), a method Yunnan’s state factories brought into production in 1973 to give in weeks what raw pu’er took years to reach. At thirty-one years it is well past the decade that marks [aged ripe pu’er](shou:age-aged), and it keeps changing slowly with the air and moisture around it, which is why storage counts as much as the years."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "696f9f29-b0e4-4920-abcc-5348ca20eec2": {"productId":"696f9f29-b0e4-4920-abcc-5348ca20eec2","paragraphs":[{"layer":"place","text":"This leaf comes from Anhua, a mountain county on the Zi river in north central Hunan, widely named as the main home of [Anhua dark tea](anhua-dark:definition) and a starting point of the old tea routes to the northwest. Like every tea made there, it began as [heimaocha](anhua-dark:making), a raw tea of large local leaf, traditionally dried over a pine fire, then steamed soft before pressing."},{"layer":"type","text":"Bailiang, a hundred liang, is one of the county's [flower rolls](anhua-dark:family), tall columns named by their old weight and sitting between the thousand and the ten. A roll is packed into a woven bamboo basket lined with leaf and [pressed tight by treading and twisting](anhua-dark:rolls) with long bars, then left to dry slowly in sun and night air for weeks. The rolls grew out of the border trade under the [Qing](anhua-dark:history)."},{"layer":"age","text":"Made in 2006, it has now had twenty years. Tea from the area is [kept for years](anhua-dark:ageing) in the belief that it improves, though no agreed count of years marks it as aged; what matters is that it stays clean, dry and aired, away from mould and other smells."}],"brewing":{"layer":"brewing","text":"From a brick, cake or basket, ease the leaf off along the edge or from the top with a pick rather than snapping it. Whole pieces give up their flavour steadily; crumbs release it all at once and cloud the cup. In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"aged Anhua dark tea","text":"A redder liquor, a sweeter, mellower cup, and sometimes a medicinal or herbal note."},"missing":[]},
  "7400ece7-a8ed-4328-b462-ac18178b9dfa": {"productId":"7400ece7-a8ed-4328-b462-ac18178b9dfa","paragraphs":[{"layer":"lot","text":"A loose [Liu Bao](liu-bao:definition) from 1990, which reaches us through the Guangzhou tea trade. That is the old road for this tea: it went by boat down the river to Wuzhou, on to Guangzhou, and out by sea to the labourers of Southeast Asia who drank it, a route the trade calls the [Nanyang trade](liu-bao:nanyang-trade)."},{"layer":"place","text":"The leaf comes from Cangwu County, near Wuzhou in Guangxi, where the tea takes its name from the town of Liubao. Like every [dark tea](dark:definition), it was piled after it was made, so that warmth, moisture and microbes could turn it darker and softer before it was packed away to age."},{"layer":"age","text":"At thirty-six years it is far past the ten that the trade sets for [aged Liu Bao](liu-bao:age-aged). Where a lot like this was kept shapes it as much as the years have."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "74e4d411-449f-41d8-a425-9298a71a08ba": {"productId":"74e4d411-449f-41d8-a425-9298a71a08ba","paragraphs":[{"layer":"type","text":"[Meizhan](yancha:meizhan) is a Fujian cultivar that came from Anxi. This leaf grew in the Wuyi Mountains and was made as [Wuyi rock tea](yancha:definition), a name only tea from that area may carry. Meizhan is less well known than Rougui and Shui Xian, and it is not one of the four famous bushes of Wuyi. Like other rock tea, it was twisted into long strips and finished over charcoal. The [roast](yancha:making) is given in several rounds with weeks or months of rest between them, which dries the leaf so it keeps."},{"layer":"age","text":"This tea was made in 2024, so it is two years old. Rock tea is labelled by its [roast level](yancha:roast-levels), and the heavier the roast, the longer a tea is said to stay good. Stored tea is kept sealed, dry and cool, because damp is what makes it [go green again](yancha:ageing)."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Wuyi rock tea","text":"Roast and stone fruit, a mineral, rocky texture and a long, sweet, mouth-watering finish. Light roast is bright and floral, medium roast fruity and rounded, full roast charcoal, wood and roasted nuts. Da Hong Pao is often floral, Rougui spicy with cinnamon, young Shui Xian sweet and smooth, and old-bush Shui Xian woody and mossy."},"missing":[]},
  "76396f61-48ec-4bd6-bcf1-dd22c73633f4": {"productId":"76396f61-48ec-4bd6-bcf1-dd22c73633f4","paragraphs":[{"layer":"lot","text":"A loose [first-grade](anhua-dark:grades) [Anhua dark tea](anhua-dark:definition), made in 2020 from spring leaf grown in cultivated gardens. The county's raw leaf is sorted into numbered grades, and each finished tea draws on the grade that suits it. Anhua sits in the mountains on the Zi river in north-central Hunan, and its name is a protected origin in China, tied to a defined place of making."},{"layer":"age","text":"Every tea from the area begins as one raw tea, [heimaocha](anhua-dark:making): large leaf fixed, rolled, piled and rolled again before it is dried. At six years this one is still young for a tea that is kept for years and said to improve, though the trade has no agreed count of years that makes one [aged](anhua-dark:ageing). It is best kept clean, dry and aired, away from mould and other smells."}],"brewing":{"layer":"brewing","text":"In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"Anhua dark tea","text":"Pine smoke or pine resin above all, a sweet taste and aftertaste, and a mellow, thick, smooth cup; a liquor from yellow and orange to orange-red. Young tea is often smokier in the first infusions and a little bitter, sweetening as the infusions go on."},"missing":[]},
  "7871ff39-1980-4edc-b5cb-edebf5a62232": {"productId":"7871ff39-1980-4edc-b5cb-edebf5a62232","paragraphs":[{"layer":"type","text":"[Meizhan](yancha:meizhan) is a Fujian cultivar that came from Anxi. It is also made as [rock tea](yancha:definition), though it is not one of the four famous bushes. This leaf is from the Wuyi Mountains of northern Fujian, where the bushes root among rock in cliff country. Like other rock tea, it was finished with a [charcoal roast](yancha:making) given in several rounds, with weeks or months between them, and that roast is what dries the leaf so it keeps."},{"layer":"age","text":"It was made in 1981 and has had forty-five years to change. Rock tea [put away for ageing](yancha:ageing) is the medium to full roast kind, because the heavier the roast, the longer the tea is said to stay good. Damp is the danger in storage. It lets kept tea go green again, which is why rock tea is held sealed, dry and cool, and why a tea that has turned is sometimes roasted again at low heat, losing a little quality each time."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"aged Wuyi rock tea","text":"A smoother, thicker liquor with less sharpness, the roast softened and the high aroma faded."},"missing":[]},
  "78bdc812-b5da-47fb-88a9-b8d9cb69ad3a": {"productId":"78bdc812-b5da-47fb-88a9-b8d9cb69ad3a","paragraphs":[{"layer":"named","text":"[Da Hong Pao](yancha:da-hong-pao), Big Red Robe, began with six old bushes on a cliff at Jiulongke in Wuyi, known as the mother trees, and no one has picked them since 2006. Most tea sold under the name today blends several Wuyi cultivars. A purebred line also exists: Qidan, grown from cuttings of those six bushes."},{"layer":"type","text":"It is a [Wuyi rock tea](yancha:definition), the [partly oxidised](oolong:definition) tea of the mountains around Wuyishan City in northern Fujian, and only leaf from that area may carry the name. The bushes grow among rock, in crevices and on ledges and terraces, in soil weathered from the cliffs. The leaf is twisted into long thin strips and finished over charcoal in several rounds, with weeks or months of rest between them. This [roast](yancha:making) dries the tea so that it keeps."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Wuyi rock tea","text":"Roast and stone fruit, a mineral, rocky texture and a long, sweet, mouth-watering finish. Light roast is bright and floral, medium roast fruity and rounded, full roast charcoal, wood and roasted nuts. Da Hong Pao is often floral, Rougui spicy with cinnamon, young Shui Xian sweet and smooth, and old-bush Shui Xian woody and mossy."},"missing":[]},
  "9b5b05f1-a6d6-4651-9126-0fe42c5c5e86": {"productId":"9b5b05f1-a6d6-4651-9126-0fe42c5c5e86","paragraphs":[{"layer":"named","text":"A loose [Liu Bao](liu-bao:definition) from Guangxi, made in the 1990s, that has been abroad and come home. The shop traces it from Guangzhou to storage in Malaysia and Singapore, then back to Guangzhou. That round trip is what [returned](malaysian-returned-liu-bao:returned) means, huiliu in Chinese: the Malaysia in its name marks a stop in the life of the tea, not the place the leaf was grown."},{"layer":"named","text":"It travelled an old road. Liu Bao was made for Chinese miners and labourers in Malaya, above all in the [tin mines](liu-bao:nanyang-trade), where the trade believed it eased the heat and damp of the work. A trade account published in 1951 follows the tea downriver, onto a larger wooden boat at Libu for Fengkai and then a powered vessel for Guangzhou, with [Ipoh and Kuala Lumpur](malaysian-returned-liu-bao:river-trade) among its final markets. Older tea from that trade later found buyers back in China."},{"layer":"age","text":"At thirty-one years it is far past the ten the trade needs to count a Liu Bao as [aged](liu-bao:age-aged), and its years overseas are part of that age: where a Liu Bao was stored matters as much as how long."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "a0ee5133-19c6-4828-9765-e0cba1275788": {"productId":"a0ee5133-19c6-4828-9765-e0cba1275788","paragraphs":[{"layer":"type","text":"[Lapsang Souchong](lapsang:definition) is the Western name, taken from the Fuzhou dialect, for Zhengshan Xiaozhong, the red tea of Tongmu in the Wuyi mountains of northern Fujian. It is called [the oldest red tea](lapsang:history), though the dates given for its beginning differ, and it reached Europe through Dutch and then British trade under names such as Bohea and Souchong. Like every [red tea](red:definition), the tea English calls black, it is fully oxidised: the leaf's own enzymes turn it from green to reddish brown."},{"layer":"type","text":"The leaf is withered, rolled and left in covered baskets or cloth bags for some hours until it turns copper. It then goes through a [hot pan](lapsang:making), which stops the oxidation fast, and is rolled again while hot to shape the strip. In the traditional way it is dried over local pine in a [qinglou](lapsang:smoke), a wooden house of several floors with the fire at the bottom and the leaf on bamboo mats above, so the heat and smoke rise through it. Since about 2005 an unsmoked red tea has been made in the same villages beside it."}],"brewing":{"layer":"brewing","text":"In a cup or pot, use about 3 grams for 240 ml, with water at 90 to 100°C, and steep about two to five minutes, usually around three. Gongfu style, use about 5 grams in a 100 to 110 ml gaiwan or pot, with short steeps that grow a little longer each round. Too hot or too long and the smoke turns harsh and bitter and covers the tea."},"notice":{"layer":"notice","styleName":"Lapsang Souchong","text":"In the smoked tea: pine and pine resin, longan or dried longan, campfire or woodsmoke, dried fruit and a sweet aftertaste. In the unsmoked tea: honey, longan and fruit or flowers."},"missing":[]},
  "a3e29766-eaa5-49c1-9ac7-15fc9d0fe3d2": {"productId":"a3e29766-eaa5-49c1-9ac7-15fc9d0fe3d2","paragraphs":[{"layer":"lot","text":"A loose Liu Bao from the 1990s, kept the old way: packed into a bamboo basket lined with bamboo leaves, where the leaf could breathe through its decades of rest. It was stored in Guangzhou, the city the river trade once passed through on its way [out by sea](liu-bao:nanyang-trade) to the miners of Southeast Asia."},{"layer":"age","text":"That puts it well past the ten years after which the trade counts a Liu Bao as [aged](liu-bao:age-aged). Where it rested matters as much as how long, which is why the basket and the city belong to its story."},{"layer":"type","text":"[Liu Bao](liu-bao:definition) is a [dark tea](dark:definition) from Cangwu County, near Wuzhou in Guangxi, named for the town of Liubao where it began. Its leaf is heaped damp after it is made, so that warmth and microbes darken and soften it, and in the [farmhouse way](liu-bao:making-traditional) it is then packed tight into baskets to age."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "b11a8bad-89d9-4518-9406-25145d4c6e2c": {"productId":"b11a8bad-89d9-4518-9406-25145d4c6e2c","paragraphs":[{"layer":"named","text":"San He means [Three Cranes](san-he-liu-bao:three-cranes), the mark of Wuzhou Tea Factory, whose birds come from Hegang Tower beside the works. The factory opened for the export trade in 1953 and registered the mark in October 1991, early in the decade this [Liu Bao](liu-bao:definition) was made."},{"layer":"named","text":"The factory dates its [cold-water piling](san-he-liu-bao:cold-water-piling) to 1958: workers wet the leaf and heap it so it darkens, a steadier route than the [farmhouse steaming](liu-bao:making-factory). The tea then rests in [handwoven bamboo baskets](san-he-liu-bao:basket-weavers), whose weave holds its shape and lets air through, inside a [brick and timber aging warehouse](san-he-liu-bao:aging-warehouse) begun the year the factory opened, its wooden boards there to moderate moisture and temperature."},{"layer":"age","text":"The shop records Guangzhou as a storage stop for this tea. At thirty-one years it is three times past the decade after which the trade counts a Liu Bao as [aged](liu-bao:age-aged), and where it was kept has shaped it as much as how long."}],"brewing":{"layer":"brewing","text":"Liu Bao takes very hot or boiling water, because its leaf is dense and gives up its depth slowly. Rinse it once or twice and pour the rinse away. Use about 5 to 8 grams to 100 ml, start with steeps of five to fifteen seconds and add a few seconds each round; a good Liu Bao gives ten cups or more."},"notice":{"layer":"notice","styleName":"aged Liu Bao","text":"A deep red, thick cup with woody, herbal and betel nut notes; tea several decades old is often described with ginseng and camphor."},"missing":[]},
  "b742891e-c6b5-46b7-877b-e7b68391b51d": {"productId":"b742891e-c6b5-46b7-877b-e7b68391b51d","paragraphs":[{"layer":"age","text":"A loose [red tea](red:definition) from the Wuyi Mountains of Fujian, dated 1920. At one hundred and six years it stands outside anything the style itself describes: Lapsang has no recognised tradition of [long ageing](lapsang:ageing), and no category of decades-old red tea is set down. It is kept the way Lapsang is kept. It stays sealed, dry, cool and away from light, because a smoky tea scents whatever sits near it."},{"layer":"type","text":"[Zhengshan Xiaozhong](lapsang:definition) is the red tea of Tongmu, in the Wuyi mountains of northern Fujian. Lapsang Souchong is the name the West took for it from the Fuzhou dialect. Traditionally the leaf is dried over a fire of local pine in a [qinglou](lapsang:smoke). This is a wooden drying house of several floors, with the fire at the bottom and the leaf on bamboo mats above, so the heat and smoke rise through it. The tea reached Europe first through Dutch and then British trade, under names such as Bohea and Souchong. It is often called the [oldest red tea](lapsang:history), though the dates given for its beginning differ."}],"brewing":{"layer":"brewing","text":"In a cup or pot, use about 3 grams for 240 ml, with water at 90 to 100°C, and steep about two to five minutes, usually around three. Gongfu style, use about 5 grams in a 100 to 110 ml gaiwan or pot, with short steeps that grow a little longer each round. Too hot or too long and the smoke turns harsh and bitter and covers the tea."},"notice":{"layer":"notice","styleName":"aged Lapsang Souchong","text":"The smoke softer and further back, with dried fruit coming forward."},"missing":[]},
  "bb692acb-b4a0-4114-afa8-c9644140eb5f": {"productId":"bb692acb-b4a0-4114-afa8-c9644140eb5f","paragraphs":[{"layer":"lot","text":"This loose ripe pu’er comes from the highlands of northern Vietnam, near the Yunnan border. Ripe pu’er is made by fermenting tea leaves in a damp pile, a process called [wet piling](shou:wet-piling)."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "c95f9820-09ef-4115-b987-4438bf2a2482": {"productId":"c95f9820-09ef-4115-b987-4438bf2a2482","paragraphs":[{"layer":"type","text":"Rougui is a [Wuyi cultivar](yancha:rougui) whose name means cassia, after cassia bark. It dates from the Qing dynasty and is now widely planted in the [Wuyi mountains](yancha:definition) of northern Fujian, where the bushes grow among rock, in crevices, on ledges and on cliff terraces, in soil weathered from the stone."},{"layer":"type","text":"The leaf is made as an [oolong](oolong:definition), partly oxidised, and twisted into long thin strips. What sets it apart is the [charcoal roast](yancha:making), given in several rounds with rests of weeks or months between them. The roast dries the tea so that it keeps, and its strength is matched to the leaf."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Wuyi rock tea","text":"Roast and stone fruit, a mineral, rocky texture and a long, sweet, mouth-watering finish. Light roast is bright and floral, medium roast fruity and rounded, full roast charcoal, wood and roasted nuts. Da Hong Pao is often floral, Rougui spicy with cinnamon, young Shui Xian sweet and smooth, and old-bush Shui Xian woody and mossy."},"missing":[]},
  "cb7efd7b-9da6-4dc8-be76-3c7e69bdb02e": {"productId":"cb7efd7b-9da6-4dc8-be76-3c7e69bdb02e","paragraphs":[{"layer":"named","text":"Y562 is a loose ripe pu’er from Yunnan that drinkers nicknamed the [little black box](y562:little-black-box) after its export carton. A tiger coming down a hillside appears on the Jixing mark. This lot is dated 1993."}],"missing":[]},
  "d8b6bcc0-e5d1-4ed1-8cab-67b3bd62d0dc": {"productId":"d8b6bcc0-e5d1-4ed1-8cab-67b3bd62d0dc","paragraphs":[{"layer":"lot","text":"A [ripe pu’er](shou:definition) from Yunnan, kept as loose leaf rather than pressed, and aged loose after it was made."},{"layer":"type","text":"Before the ageing began, the leaf went through the [wet pile](shou:wet-piling). Leaf dried in the sun is wetted and heaped so that heat, moisture and microbes can work on it. The microbes make their own heat, so the heap is covered to hold it in and turned about once a week to spread it and let in air, and it is kept below about 65°C so the leaf does not char. Yunnan’s state factories brought the method into production in 1973, to reach in weeks what raw pu’er reached only after years of waiting."}],"brewing":{"layer":"brewing","text":"Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "da83f352-9402-437e-867e-412b6f0b5df8": {"productId":"da83f352-9402-437e-867e-412b6f0b5df8","paragraphs":[{"layer":"lot","text":"Wild Ancha is a loose [Anhua dark tea](anhua-dark:definition) picked from wild plants. Anhua is a mountain county on the Zi river in north central Hunan, and its tea is a protected origin product in China, tied to a defined place of making. The county is widely named as the main home of dark tea in China, and as a starting point of the old tea routes to the northwest."},{"layer":"type","text":"Like every Anhua tea, it begins as [heimaocha](anhua-dark:making), a raw tea of large Anhua leaf that is fixed, rolled, piled, rolled again and dried. What makes it a [dark tea](dark:definition) comes after that making: left in warmth and moisture, the leaf is slowly darkened and changed by microbes and its own chemistry."},{"layer":"age","text":"At two years this tea is young. Anhua tea is [kept for years](anhua-dark:ageing) and said to improve with keeping, though no agreed count of years marks it as aged. It is best kept clean, dry and aired, away from mould and other smells."}],"brewing":{"layer":"brewing","text":"In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"Anhua dark tea","text":"Pine smoke or pine resin above all, a sweet taste and aftertaste, and a mellow, thick, smooth cup; a liquor from yellow and orange to orange-red. Young tea is often smokier in the first infusions and a little bitter, sweetening as the infusions go on."},"missing":[]},
  "dac9d851-44ca-4789-b561-01bc3dc9a6ae": {"productId":"dac9d851-44ca-4789-b561-01bc3dc9a6ae","paragraphs":[{"layer":"type","text":"A small tuo of [ripe pu’er](shou:definition) made in 1998 from Yunnan leaf. Before it was pressed, the leaf went through the [wet pile](shou:wet-piling). It was heaped warm and damp and turned now and then to spread the heat and let air in. That places it in the style’s third decade, because the method reached production in 1973, twenty-five years earlier."},{"layer":"age","text":"At twenty-eight years it counts as [aged ripe pu’er](shou:age-aged) in the trade’s terms. The leaf keeps changing slowly with the air and moisture around it, so how a tuo like this was kept matters as much as how long."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"aged ripe pu’er","text":"A smooth, deep cup with woody, date-like or medicinal notes, which the trade calls aged aroma."},"missing":[]},
  "dddd11d2-7357-4d91-86e8-52a99bb47c51": {"productId":"dddd11d2-7357-4d91-86e8-52a99bb47c51","paragraphs":[{"layer":"place","text":"Naka is a village in [Mengsong](menghai-county:mengsong-naka), one of Menghai County’s tea-growing areas. This tea is a ripe pu’er pressed into a cake."}],"missing":[]},
  "de14c4e4-2170-4a2f-9476-d4a1c29dcabc": {"productId":"de14c4e4-2170-4a2f-9476-d4a1c29dcabc","paragraphs":[{"layer":"grade","text":"This is [first grade](anhua-dark:grades) (一级) leaf from Anhua, picked in 2015 and kept loose. In Anhua the raw leaf is sorted into numbered grades, and each grade goes into the finished tea that suits it."},{"layer":"type","text":"Anhua County is a mountain county on the Zi river in north-central Hunan. Its [dark tea](anhua-dark:definition) is a protected origin product, so the name is tied to tea made in that place. Like every tea from the county, this one began as [heimaocha](anhua-dark:making), a raw tea of large Anhua leaf that is fixed, rolled, piled, rolled again and dried. The leaf then goes on changing slowly in warmth and moisture, which is why the trade calls [dark tea](dark:definition) post-fermented."},{"layer":"age","text":"Eleven years have passed since this leaf was made. No set number of years makes an Anhua tea [aged](anhua-dark:ageing). It is best kept clean, dry and aired, away from mould and other smells."}],"brewing":{"layer":"brewing","text":"In a small pot or gaiwan, use water at the boil and start with a steep of about 15 to 30 seconds, a little longer each round. Pressed and aged Anhua tea is also commonly simmered in a pot."},"notice":{"layer":"notice","styleName":"aged Anhua dark tea","text":"A redder liquor, a sweeter, mellower cup, and sometimes a medicinal or herbal note."},"missing":[]},
  "dfb90ef0-fe35-4bc2-a1c5-17084f1f66d4": {"productId":"dfb90ef0-fe35-4bc2-a1c5-17084f1f66d4","paragraphs":[{"layer":"lot","text":"This ripe pu’er cake comes from the Yiwu tea area of Yunnan. Its recorded year is 2008."}],"missing":[]},
  "dfde3e28-c848-4116-ba2b-ea55590b0f1e": {"productId":"dfde3e28-c848-4116-ba2b-ea55590b0f1e","paragraphs":[{"layer":"type","text":"Lotus Rougui is a [Rougui](yancha:rougui) from the Wuyi Mountains of northern Fujian, a cultivar of the area that dates from the Qing dynasty and is now planted widely across it. As [Wuyi rock tea](yancha:definition), a partly oxidised [oolong](oolong:definition), it comes from bushes grown among rock, on ledges and terraces in cliff country, in soil weathered from that rock. Only tea from this area may be sold under the name."},{"layer":"type","text":"The leaf is twisted into long strips rather than rolled, then finished over charcoal in several rounds, with rests of weeks or months between them. That [charcoal roast](yancha:making) dries the tea so it keeps, and the maker sets its strength by the leaf it is given."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Wuyi rock tea","text":"Roast and stone fruit, a mineral, rocky texture and a long, sweet, mouth-watering finish. Light roast is bright and floral, medium roast fruity and rounded, full roast charcoal, wood and roasted nuts. Da Hong Pao is often floral, Rougui spicy with cinnamon, young Shui Xian sweet and smooth, and old-bush Shui Xian woody and mossy."},"missing":[]},
  "e342e878-b5c8-4433-8a22-9af8265376c6": {"productId":"e342e878-b5c8-4433-8a22-9af8265376c6","paragraphs":[{"layer":"lot","text":"A cake of [ripe pu’er](shou:definition) from Wuliang Mountain, in Jingdong County, Pu’er City, pressed in 2019. At seven years it sits in the span where the [smell of the pile](shou:age-settling) has usually aired away."},{"layer":"type","text":"Before pressing, the leaf was wetted and heaped in a [fermenting pile](shou:wet-piling). The pile is covered to hold in the heat its own microbes make. It is turned about once a week to spread that heat and let air in, and it is kept cool enough that the leaf does not char. The method was made to give in weeks what raw pu’er reaches only after years of ageing. Yunnan’s state factories brought it into production in 1973."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "e5e7c9ec-d66b-48de-9197-272ffdb638e0": {"productId":"e5e7c9ec-d66b-48de-9197-272ffdb638e0","paragraphs":[{"layer":"lot","text":"Xiniu Tang (犀牛塘) means “Rhinoceros Pond.” This tea is a ripe pu’er pressed into a cake."}],"brewing":{"layer":"brewing","text":"From a cake, brick or tuo, ease a piece off along the edge with a pick rather than snapping it. Whole leaves give up their flavour steadily; broken ones release it all at once and cloud the cup. Ripe pu’er takes boiling water: fermented, tightly packed leaf needs full heat to open, and it does not scald the way green tea can. A common start is about 7 grams to 100 ml and one quick rinse, which wakes the leaf and carries off dust and any pile smell. Then short steeps that lengthen as the leaf opens, so the cup stays clear rather than heavy; it gives eight or more good cups."},"notice":{"layer":"notice","styleName":"ripe pu’er","text":"A smooth, sweet cup with earthy or woody notes. A young ripe tea can carry a faint smell of the pile, which fades with airing or in the first steeps."},"missing":[]},
  "e77d2550-f9d0-4965-850a-d2b2096fb71f": {"productId":"e77d2550-f9d0-4965-850a-d2b2096fb71f","paragraphs":[{"layer":"place","text":"Zhuangyuan Hong is a loose leaf tea from the Wuyi Mountains in northern Fujian, the home of [Wuyi rock tea](yancha:definition). The bushes there grow among rock, in crevices and on ledges and terraces in cliff country, rooted in soil weathered from that same stone and kept wet by fog and rain. Only tea grown in this protected area may be sold as Wuyi rock tea."},{"layer":"type","text":"[Oolong](oolong:definition) took shape in these mountains between the sixteenth and seventeenth centuries, at the turn from the Ming to the Qing. Wuyi leaf is twisted into long thin strips rather than rolled into balls, then [roasted over charcoal](yancha:making) in several rounds, with rests of weeks or months between them. The roast dries the leaf so it keeps, and the maker sets its strength by the leaf in hand."}],"brewing":{"layer":"brewing","text":"Wuyi tea is usually brewed gongfu style with water at or near the boil, about 95 to 100°C, and about 5 to 8 grams of leaf in a 100 to 120 ml gaiwan, a third to a half full. A quick rinse, poured off at once, is common. Steeps start short, about 5 to 20 seconds, and grow a few seconds longer each round, and good rock tea gives seven steeps or more. In a larger pot, use about 2 to 5 grams for 250 to 350 ml and steep two to three minutes."},"notice":{"layer":"notice","styleName":"Wuyi rock tea","text":"Roast and stone fruit, a mineral, rocky texture and a long, sweet, mouth-watering finish. Light roast is bright and floral, medium roast fruity and rounded, full roast charcoal, wood and roasted nuts. Da Hong Pao is often floral, Rougui spicy with cinnamon, young Shui Xian sweet and smooth, and old-bush Shui Xian woody and mossy."},"missing":[]},
  "e949b585-5f07-411b-82fb-7da7355edc77": {"productId":"e949b585-5f07-411b-82fb-7da7355edc77","paragraphs":[{"layer":"lot","text":"A cake of [raw pu’er](sheng:identity) from Yiwu in Yunnan, made in 2004, which has rested since in Guangzhou’s tea trade. Its leaf was fried in a wok and dried in the sun but never [hot-air dried](sheng:making), so some of its own activity survived, and that is what lets a cake like this keep changing. Without shou’s fermenting pile, raw pu’er [changes slowly in storage](sheng:aging) instead, and because [heat and humidity](sheng:storage) set the pace, where a cake has been kept belongs to its history."},{"layer":"age","text":"At twenty-two years it has passed the twenty that many in the trade wait for before they call raw pu’er [aged](sheng:ageing), though some count from ten. How far it has come depends as much on that storage as on the years."}],"brewing":{"layer":"brewing","text":"Pry the leaf off a cake or brick in chunks with a pick or knife, from the surface and toward the centre, rather than crumbling it. A mix of larger pieces and smaller ones brews evenly. Young raw pu’er takes water a little off the boil, about 85 to 95°C, because hotter water draws out more of its bitterness; an aged one takes 95°C to boiling. A common start is about 7 grams to 100 ml and a quick rinse of a few seconds, then a first steep of ten to fifteen seconds, adding a few seconds each round. A good raw tea gives eight to ten cups or more."},"notice":{"layer":"notice","styleName":"aged Sheng Pu’er","text":"A smoother, thicker, sweeter cup with woody, herbal and camphor notes and something of dried dates or dark fruit."},"missing":[]},
  "fb92f73e-a1f2-4740-bb14-110726deae71": {"productId":"fb92f73e-a1f2-4740-bb14-110726deae71","paragraphs":[{"layer":"type","text":"Zhengshan Xiaozhong is a [red tea](red:definition), the fully oxidised tea English calls black, from the Wuyi Mountains of northern Fujian. The style belongs to Tongmu, whose home villages and gardens lie inside the mountains' nature reserve. [Zhengshan](lapsang:definition), true mountain, names that core; tea made the same way beyond it is called waishan. Abroad it goes by Lapsang Souchong, a name taken from the Fuzhou dialect."},{"layer":"type","text":"It is counted as the [oldest red tea](lapsang:history), though the dates given for its beginning differ, and it reached Europe through Dutch and then British trade. In the making, the oxidised leaf goes into a hot pan, [guo hong guo](lapsang:making), which halts oxidation quickly, and is rolled again while hot to shape the strip. The traditional tea is then dried over local pine in a [qinglou](lapsang:smoke), a wooden house of several floors with the fire at the bottom, so the heat and smoke rise through leaf laid on bamboo mats above."}],"brewing":{"layer":"brewing","text":"In a cup or pot, use about 3 grams for 240 ml, with water at 90 to 100°C, and steep about two to five minutes, usually around three. Gongfu style, use about 5 grams in a 100 to 110 ml gaiwan or pot, with short steeps that grow a little longer each round. Too hot or too long and the smoke turns harsh and bitter and covers the tea."},"notice":{"layer":"notice","styleName":"Lapsang Souchong","text":"In the smoked tea: pine and pine resin, longan or dried longan, campfire or woodsmoke, dried fruit and a sweet aftertaste. In the unsmoked tea: honey, longan and fruit or flowers."},"missing":[]},
};
